1. /**
2.  * Boot scene: generates all procedural assets and shows a title screen.
3.  */
4. 
5. import * as Phaser from "phaser";
6. import { generateAllTextures, generatePlayerTextureWithHair } from "../renderers/textures";
7. import { PLAYER_CLASSES, type PlayerClass } from "../systems/classes";
