35.   calcPanelLayout,
36.   createDimGraphics,
37.   createOverlayContainer,
38.   createPanelGraphics,
39. } from "../utils/ui";
40. 
41. 
42. export class BootScene extends Phaser.Scene {
43.   private readonly sceneTransitions = new SceneTransitionManager(this);
44. 
45.   constructor() {
46.     super({ key: "BootScene" });
47.   }
48. 
49.   preload(): void {
50.     // No external assets to load - we generate everything procedurally
51.   }
52. 
53.   create(): void {
54.     this.sceneTransitions.prepare();
55.     installSceneAccessibility(this);
56.     generateAllTextures(this);
57.     this.showTitleScreen();
58.   }
59. 
60. 
61.   /** Format class info string for the selection panel. */
62.   private formatClassInfo(app: PlayerClass): string {
63.     const boostParts = Object.entries(app.statBoosts)
64.       .map(([k, v]) => `${k.slice(0, 3).toUpperCase()}+${v}`)
65.       .join(", ");
66.     return `${app.playstyle} | ${boostParts} | d${app.hitDie} HP`;
67.   }
68. 
69. 
70.   private showTitleScreen(): void {
71.     debugPanelState("BOOT | Screen: title");
72.     const cx = this.cameras.main.centerX;
73.     const cy = this.cameras.main.centerY;
74. 
75.     this.cameras.main.setBackgroundColor(0x0a0a1a);
76. 
77.     // Initialize audio on first pointer interaction (browsers require user gesture)
78.     this.input.once("pointerdown", () => {
79.       audioEngine.init();
80.       audioEngine.playTitleMusic();
81.     });
82.     // Also initialize on first keyboard press
83.     this.input.keyboard!.once("keydown", () => {
84.       audioEngine.init();
85.       audioEngine.playTitleMusic();
86.     });
87. 
88.     // ── Favicon / Logo: procedurally draw the D20 die ──
89.     const logoSize = 72;
90.     const lx = cx;
91.     const ly = cy - 120;
92.     const logo = this.add.graphics();
93.     // D20 hexagon shape
94.     const pts = [
95.       { x: 0, y: -logoSize / 2 },
96.       { x: logoSize * 0.45, y: -logoSize / 4 },
97.       { x: logoSize * 0.45, y: logoSize / 4 },
98.       { x: 0, y: logoSize / 2 },
99.       { x: -logoSize * 0.45, y: logoSize / 4 },
100.       { x: -logoSize * 0.45, y: -logoSize / 4 },
101.     ];
102.     logo.fillStyle(0x1a1a2e, 1);
103.     logo.beginPath();
104.     logo.moveTo(lx + pts[0].x, ly + pts[0].y);
105.     for (let i = 1; i < pts.length; i++) logo.lineTo(lx + pts[i].x, ly + pts[i].y);
106.     logo.closePath();
107.     logo.fillPath();
108.     logo.lineStyle(2.5, 0xffd700, 1);
109.     logo.beginPath();
110.     logo.moveTo(lx + pts[0].x, ly + pts[0].y);
111.     for (let i = 1; i < pts.length; i++) logo.lineTo(lx + pts[i].x, ly + pts[i].y);
112.     logo.closePath();
113.     logo.strokePath();
114.     // Inner facet lines
115.     logo.lineStyle(1, 0xffd700, 0.4);
116.     logo.lineBetween(lx + pts[0].x, ly + pts[0].y, lx + pts[3].x, ly + pts[3].y);
117.     logo.lineBetween(lx + pts[5].x, ly + pts[5].y, lx + pts[2].x, ly + pts[2].y);
118.     logo.lineBetween(lx + pts[4].x, ly + pts[4].y, lx + pts[1].x, ly + pts[1].y);
119.     // "2D" text on the die
120.     this.add.text(lx, ly + 4, "2D", {
121.       fontSize: "24px", fontFamily: "monospace", fontStyle: "bold", color: "#ffd700",
122.     }).setOrigin(0.5);
123. 
124.     // Game title below logo
125.     this.add
126.       .text(cx, ly + logoSize / 2 + 18, "2D&D", {
127.         fontSize: "48px",
128.         fontFamily: "monospace",
129.         color: "#ffd700",
130.         stroke: "#000",
131.         strokeThickness: 4,
132.       })
133.       .setOrigin(0.5);
134. 
135.     this.add
136.       .text(cx, ly + logoSize / 2 + 60, "An epic tale of magic and dice, in 2d!", {
137.         fontSize: "13px",
138.         fontFamily: "monospace",
139.         color: "#888",
140.       })
